from typing import List

def find_kth_smallest(list1: List[int], list2: List[int], k: int) -> int:
    """
    Finds the kth smallest element in the union of two sorted lists.

    Args:
    list1: A sorted list of integers.
    list2: A sorted list of integers.
    k: The kth position to find the smallest element for (1-indexed).

    Returns:
    The kth smallest element in the union of list1 and list2.
    """
    def find_kth_smaller(index1, index2, kth):
        if index1 >= len(list1):
            return list2[index2 + kth - 1]
        if index2 >= len(list2):
            return list1[index1 + kth - 1]
        if kth == 1:
            return min(list1[index1], list2[index2])

        mid_val1 = list1[index1 + kth // 2 - 1] if index1 + kth // 2 - 1 < len(list1) else float('inf')
        mid_val2 = list2[index2 + kth // 2 - 1] if index2 + kth // 2 - 1 < len(list2) else float('inf')

        if mid_val1 < mid_val2:
            return find_kth_smaller(index1 + kth // 2, index2, kth - kth // 2)
        else:
            return find_kth_smaller(index1, index2 + kth // 2, kth - kth // 2)

    return find_kth_smaller(0, 0, k)

